package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.Assert.*;
public class PoseStudyTest {
 @Test public void originalSourceLockAndPreservedEnginesRemainExact() throws Exception {Path r=Path.of("").toAbsolutePath();while(r!=null&&!Files.exists(r.resolve("docs/POSE_034_CANDIDATE_LOCK.json")))r=r.getParent();assertNotNull(r);for(String name:List.of("docs/POSE_034_CANDIDATE_LOCK.json","docs/POSE_034_FROZEN_CONTRACT.json")){var data=new JSONObject(Files.readString(r.resolve(name)));var files=data.optJSONArray("sources");if(files==null)files=data.getJSONArray("preservedSources");for(Object raw:files){var f=(JSONObject)raw;assertEquals(f.getString("path"),f.getString("sha256"),MapDefinition.sha(Files.readString(r.resolve(f.getString("path"))).replace("\r\n","\n").getBytes(StandardCharsets.UTF_8)));}}var contract=new JSONObject(Files.readString(r.resolve("docs/POSE_034_FROZEN_CONTRACT.json")));assertEquals(contract.getString("suiteUtf8LfSha256"),MapDefinition.sha(Files.readString(r.resolve("workspace-engine/src/main/resources/pose-tasks034.json")).replace("\r\n","\n").getBytes(StandardCharsets.UTF_8)));}
 @Test public void firstDifferentReservedMeasurementRetainsOriginalNativeFeatureAblation() throws Exception {Path root=Files.createTempDirectory("pose034-study-");String id=UUID.randomUUID().toString();try(var store=new PoseStudyStore(root)){store.start(id,UUID.randomUUID().toString());JSONObject j=null;for(int i=0;i<48000;i++){j=store.read(id);if(!j.getString("status").equals("running"))break;Thread.sleep(10);}assertEquals(j.toString(),"completed",j.getString("status"));assertEquals(40,j.getJSONArray("trials").length());assertEquals(20,j.getInt("candidateFrozenAfterTrial"));var d=store.verify(id);assertTrue(d.similar(j.getJSONObject("decision")));System.out.println("POSE_STUDY_034 "+d);System.out.println("POSE_STUDY_FOLDER_034 "+root);Files.writeString(root.resolve("summary.json"),j.toString());var frames=new JSONArray();for(Object c:PoseStudyReport.charts(j))frames.put(c);var view=new JSONObject().put("visible",true).put("rows",PoseStudyReport.table(j)).put("data",PoseStudyReport.data(j)).put("frames",frames);assertTrue(PoseStudyReport.verifyView(j,view).getBoolean("passed"));var bad=new JSONObject(view.toString());bad.getJSONArray("rows").getJSONArray(0).put(2,"invented");final var finalJob=j;assertThrows(IllegalStateException.class,()->PoseStudyReport.verifyView(finalJob,bad));}}
}
